/* data/maulid/burdah.js - Qasidah Burdah (Arab, transliterasi, terjemah). Dibuat oleh template-kitab/maulid_dari_md.py.
   Satu bait = {no, ar, lt, id}. Boleh diedit langsung. */
registerMaulid({"id": "burdah", "judul": "Qasidah Burdah", "sumber": "Al-Kawakib Ad-Durriyyah, karya Imam Al-Bushiri. Disalin dari PDF Majmu'atul Mawalid; transliterasi & terjemah disusun ulang - mohon ditashih.",bagian:[
{judul:"Pembuka dan Fasal 1: Kerinduan kepada Nabi",isi:[
{"ar": "مَوْلَايَ صَلِّ وَسَلِّمْ دَائِمًا أَبَدًا ۞ عَلَى حَبِيْبِكَ خَيْرِ الْخَلْقِ كُلِّهِمِ", "lt": "Maulâya shalli wa sallim dâ'iman abadan ۞ ‘alâ ḥabîbika khairil-khalqi kullihimi", "id": "Wahai Tuhanku, limpahkanlah shalawat dan salam selalu dan selamanya kepada kekasih-Mu, sebaik-baik seluruh makhluk.", "no": 1},
{"ar": "اَلْحَمْدُ لِلّٰهِ مُنْشِي الْخَلْقِ مِنْ عَدَمٍ ۞ ثُمَّ الصَّلَاةُ عَلَى الْمُخْتَارِ فِي الْقِدَمِ", "lt": "Al-ḥamdu lillâhi munsyil-khalqi min ‘adamin ۞ tsummash-shalâtu ‘alal-mukhtâri fil-qidami", "id": "Segala puji bagi Allah yang menciptakan makhluk dari ketiadaan, kemudian shalawat atas (Nabi) yang terpilih sejak dahulu kala.", "no": 2},
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 3},
{"ar": "أَمِنْ تَذَكُّرِ جِيْرَانٍ بِذِيْ سَلَمِ ۞ مَزَجْتَ دَمْعًا جَرَى مِنْ مُقْلَةٍ بِدَمِ", "lt": "Amin tadzakkuri jîrânin bidzî salami ۞ mazajta dam‘an jarâ min muqlatin bidami", "id": "Apakah karena teringat tetangga di Dzi Salam, engkau campurkan air mata yang mengalir dari kelopak mata dengan darah?", "no": 4},
{"ar": "أَمْ هَبَّتِ الرِّيْحُ مِنْ تِلْقَاءِ كَاظِمَةٍ ۞ وَأَوْمَضَ الْبَرْقُ فِي الظَّلْمَاءِ مِنْ إِضَمِ", "lt": "Am habbatir-rîḥu min tilqâ'i kâdhimatin ۞ wa aumadlal-barqu fidh-dhalmâ'i min idlami", "id": "Ataukah karena angin berembus dari arah Kadhimah, dan kilat berkilau dalam kegelapan malam dari lembah Idham?", "no": 5},
{"ar": "فَمَا لِعَيْنَيْكَ إِنْ قُلْتَ اكْفُفَا هَمَتَا ۞ وَمَا لِقَلْبِكَ إِنْ قُلْتَ اسْتَفِقْ يَهِمِ", "lt": "Famâ li‘ainaika in qultakfufâ hamatâ ۞ wa mâ liqalbika in qultas-tafiq yahimi", "id": "Mengapa kedua matamu, bila engkau katakan \"berhentilah\", justru semakin deras mengalir? Dan mengapa hatimu, bila engkau katakan \"sadarlah\", justru semakin bingung?", "no": 6},
{"ar": "أَيَحْسَبُ الصَّبُّ أَنَّ الْحُبَّ مُنْكَتِمٌ ۞ مَا بَيْنَ مُنْسَجِمٍ مِنْهُ وَمُضْطَرِمِ", "lt": "Ayaḥsabush-shabbu annal-ḥubba munkatimun ۞ mâ baina munsajimin minhu wa mudl-ṭarimi", "id": "Apakah sang perindu mengira cintanya dapat disembunyikan, padahal ada air mata yang bercucuran dan hati yang membara?", "no": 7},
{"ar": "لَوْلَا الْهَوَى لَمْ تُرِقْ دَمْعًا عَلَى طَلَلٍ ۞ وَلَا أَرِقْتَ لِذِكْرِ الْبَانِ وَالْعَلَمِ", "lt": "Laulal-hawâ lam turiq dam‘an ‘alâ ṭalalin ۞ wa lâ ariqta lidzikril-bâni wal-‘alami", "id": "Seandainya bukan karena cinta, engkau tidak akan menumpahkan air mata di atas puing-puing (rumah kekasih), dan tidak akan terjaga karena teringat pohon Ban dan bukit 'Alam.", "no": 8},
{"ar": "فَكَيْفَ تُنْكِرُ حُبًّا بَعْدَ مَا شَهِدَتْ ۞ بِهِ عَلَيْكَ عُدُوْلُ الدَّمْعِ وَالسَّقَمِ", "lt": "Fakaifa tunkiru ḥubban ba‘da mâ syahidat ۞ bihî ‘alaika ‘udûlud-dam‘i was-saqami", "id": "Bagaimana engkau mengingkari cinta, padahal saksi-saksi yang adil, yaitu air mata dan penyakit (rindu), telah bersaksi atasmu?", "no": 9},
{"ar": "وَأَثْبَتَ الْوَجْدُ خَطَّيْ عَبْرَةٍ وَضَنًى ۞ مِثْلَ الْبَهَارِ عَلَى خَدَّيْكَ وَالْعَنَمِ", "lt": "Wa atsbatal-wajdu khaṭṭai ‘abratin wa dlanan ۞ mitslal-bahâri ‘alâ khaddaika wal-‘anami", "id": "Rindu telah menorehkan dua garis air mata dan kurus kering di kedua pipimu, (pucat) seperti bunga bahar dan (merah) seperti bunga 'anam.", "no": 10},
{"ar": "نَعَمْ سَرَى طَيْفُ مَنْ أَهْوَى فَأَرَّقَنِيْ ۞ وَالْحُبُّ يَعْتَرِضُ اللَّذَّاتِ بِالْأَلَمِ", "lt": "Na‘am sarâ ṭaifu man ahwâ fa arraqanî ۞ wal-ḥubbu ya‘taridlul-ladz-dzâti bil-alami", "id": "Ya, bayangan orang yang kucintai datang di malam hari sehingga membuatku tak bisa tidur; memang cinta menghalangi kenikmatan dengan rasa sakit.", "no": 11},
{"ar": "يَا لَائِمِيْ فِي الْهَوَى الْعُذْرِيِّ مَعْذِرَةً ۞ مِنِّيْ إِلَيْكَ وَلَوْ أَنْصَفْتَ لَمْ تَلُمِ", "lt": "Yâ lâ'imî fil-hawal-‘udzriyyi ma‘dziratan ۞ minnî ilaika wa lau anshafta lam talumi", "id": "Wahai yang mencelaku karena cinta suci, maafkanlah aku; seandainya engkau bersikap adil, tentu engkau tidak akan mencela.", "no": 12},
{"ar": "عَدَتْكَ حَالِيْ لَا سِرِّيْ بِمُسْتَتِرٍ ۞ عَنِ الْوُشَاةِ وَلَا دَائِيْ بِمُنْحَسِمِ", "lt": "‘Adatka ḥâlî lâ sirrî bimustatirin ۞ ‘anil-wusyâti wa lâ dâ'î bimunḥasimi", "id": "Semoga keadaanku tidak menimpamu; rahasiaku tak lagi tersembunyi dari para penggunjing, dan penyakitku tak kunjung sembuh.", "no": 13},
{"ar": "مَحَضْتَنِي النُّصْحَ لٰكِنْ لَسْتُ أَسْمَعُهُ ۞ إِنَّ الْمُحِبَّ عَنِ الْعُذَّالِ فِيْ صَمَمِ", "lt": "Maḥadltanin-nush-ḥa lâkin lastu asma‘uhû ۞ innal-muḥibba ‘anil-‘udzdzâli fî shamami", "id": "Engkau tulus menasihatiku, tetapi aku tidak mendengarnya; sesungguhnya orang yang sedang jatuh cinta tuli terhadap para pencela.", "no": 14},
{"ar": "إِنِّي اتَّهَمْتُ نَصِيْحَ الشَّيْبِ فِيْ عَذَلِيْ ۞ وَالشَّيْبُ أَبْعَدُ فِيْ نُصْحٍ عَنِ التُّهَمِ", "lt": "Innit-tahamtu nashîḥasy-syaibi fî ‘adzalî ۞ wasy-syaibu ab‘adu fî nush-ḥin ‘anit-tuhami", "id": "Sungguh aku telah menuduh uban yang menasihatiku sebagai pencela, padahal uban adalah penasihat yang paling jauh dari tuduhan.", "no": 15},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 16}]},
{judul:"Fasal 2: Peringatan terhadap Hawa Nafsu",isi:[
{"ar": "فَإِنَّ أَمَّارَتِيْ بِالسُّوْءِ مَا اتَّعَظَتْ ۞ مِنْ جَهْلِهَا بِنَذِيْرِ الشَّيْبِ وَالْهَرَمِ", "lt": "Fa inna ammâratî bis-sû'i mat-ta‘adhat ۞ min jahlihâ binadzîrisy-syaibi wal-harami", "id": "Sesungguhnya nafsuku yang selalu menyuruh kepada keburukan tidak mau mengambil pelajaran, karena kebodohannya, dari peringatan uban dan usia tua.", "no": 1},
{"ar": "وَلَا أَعَدَّتْ مِنَ الْفِعْلِ الْجَمِيْلِ قِرَى ۞ ضَيْفٍ أَلَمَّ بِرَأْسِيْ غَيْرَ مُحْتَشِمِ", "lt": "Wa lâ a‘addat minal-fi‘lil-jamîli qirâ ۞ dlaifin alamma bira'sî ghaira muḥtasyimi", "id": "Ia tidak menyiapkan perbuatan baik sebagai jamuan untuk tamu (uban) yang singgah di kepalaku tanpa malu-malu.", "no": 2},
{"ar": "لَوْ كُنْتُ أَعْلَمُ أَنِّيْ مَا أُوَقِّرُهُ ۞ كَتَمْتُ سِرًّا بَدَا لِيْ مِنْهُ بِالْكَتَمِ", "lt": "Lau kuntu a‘lamu annî mâ uwaqqiruhû ۞ katamtu sirran badâ lî minhu bil-katami", "id": "Seandainya aku tahu bahwa aku tidak akan menghormatinya, tentu aku akan menyembunyikan rahasia (uban) yang tampak padaku dengan pewarna.", "no": 3},
{"ar": "مَنْ لِيْ بِرَدِّ جِمَاحٍ مِنْ غَوَايَتِهَا ۞ كَمَا يُرَدُّ جِمَاحُ الْخَيْلِ بِاللُّجُمِ", "lt": "Man lî biraddi jimâḥin min ghawâyatihâ ۞ kamâ yuraddu jimâḥul-khaili bil-lujumi", "id": "Siapakah yang dapat membantuku mengendalikan keliaran nafsu dari kesesatannya, sebagaimana kuda yang liar dikendalikan dengan tali kekang?", "no": 4},
{"ar": "فَلَا تَرُمْ بِالْمَعَاصِيْ كَسْرَ شَهْوَتِهَا ۞ إِنَّ الطَّعَامَ يُقَوِّيْ شَهْوَةَ النَّهِمِ", "lt": "Falâ tarum bil-ma‘âshî kasra syahwatihâ ۞ innaṭ-ṭa‘âma yuqawwî syahwatan-nahimi", "id": "Janganlah engkau berharap dapat mematahkan syahwat nafsu dengan maksiat, karena makanan justru menguatkan syahwat orang yang rakus.", "no": 5},
{"ar": "وَالنَّفْسُ كَالطِّفْلِ إِنْ تُهْمِلْهُ شَبَّ عَلَى ۞ حُبِّ الرَّضَاعِ وَإِنْ تَفْطِمْهُ يَنْفَطِمِ", "lt": "Wan-nafsu kaṭ-ṭifli in tuhmilhu syabba ‘alâ ۞ ḥubbir-radlâ‘i wa in tafṭimhu yanfaṭimi", "id": "Nafsu itu seperti bayi; jika engkau biarkan, ia akan tumbuh tetap gemar menyusu, dan jika engkau sapih, ia pun akan berhenti.", "no": 6},
{"ar": "فَاصْرِفْ هَوَاهَا وَحَاذِرْ أَنْ تُوَلِّيَهُ ۞ إِنَّ الْهَوَى مَا تَوَلَّى يُصْمِ أَوْ يَصِمِ", "lt": "Fashrif hawâhâ wa ḥâdzir an tuwalliyahû ۞ innal-hawâ mâ tawallâ yushmi au yashimi", "id": "Palingkanlah hawa nafsunya dan waspadalah agar jangan engkau jadikan ia penguasa, karena bila hawa nafsu berkuasa, ia akan membinasakan atau mencemarkan.", "no": 7},
{"ar": "وَرَاعِهَا وَهِيَ فِي الْأَعْمَالِ سَائِمَةٌ ۞ وَإِنْ هِيَ اسْتَحْلَتِ الْمَرْعَى فَلَا تُسِمِ", "lt": "Wa râ‘ihâ wa hiya fil-a‘mâli sâ'imatun ۞ wa in hiyas-taḥlatil-mar‘â falâ tusimi", "id": "Gembalakanlah nafsu itu ketika ia sedang merumput di ladang amal, dan jika ia merasa manis dengan suatu padang rumput (maksiat), jangan biarkan ia terus merumput di sana.", "no": 8},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 9},
{"ar": "كَمْ حَسَّنَتْ لَذَّةً لِلْمَرْءِ قَاتِلَةً ۞ مِنْ حَيْثُ لَمْ يَدْرِ أَنَّ السُّمَّ فِي الدَّسَمِ", "lt": "Kam ḥassanat ladzdzatan lil-mar'i qâtilatan ۞ min ḥaitsu lam yadri annas-summa fid-dasami", "id": "Betapa sering nafsu menghias kenikmatan yang mematikan bagi seseorang, sementara ia tidak sadar bahwa racun ada di dalam lemak (makanan yang lezat).", "no": 10},
{"ar": "وَاخْشَ الدَّسَائِسَ مِنْ جُوْعٍ وَمِنْ شِبَعٍ ۞ فَرُبَّ مَخْمَصَةٍ شَرٌّ مِنَ التُّخَمِ", "lt": "Wakhsyad-dasâ'isa min jû‘in wa min syiba‘in ۞ farubba makhmashatin syarrun minat-tukhami", "id": "Takutlah terhadap tipu daya (nafsu) dari rasa lapar dan kenyang, karena betapa banyak lapar yang lebih buruk daripada kekenyangan.", "no": 11},
{"ar": "وَاسْتَفْرِغِ الدَّمْعَ مِنْ عَيْنٍ قَدِ امْتَلَأَتْ ۞ مِنَ الْمَحَارِمِ وَالْزَمْ حِمْيَةَ النَّدَمِ", "lt": "Wastafrighid-dam‘a min ‘ainin qadim-tala'at ۞ minal-maḥârimi walzam ḥimyatan-nadami", "id": "Tumpahkanlah air mata dari mata yang telah penuh dengan (memandang) yang haram, dan tetaplah berpantang dengan penyesalan.", "no": 12},
{"ar": "وَخَالِفِ النَّفْسَ وَالشَّيْطَانَ وَاعْصِهِمَا ۞ وَإِنْ هُمَا مَحَضَاكَ النُّصْحَ فَاتَّهِمِ", "lt": "Wa khâlifin-nafsa wasy-syaiṭâna wa‘shihimâ ۞ wa in humâ maḥadlâkan-nush-ḥa fattahimi", "id": "Tentanglah nafsu dan setan, durhakailah keduanya; dan bila keduanya tampak tulus menasihatimu, curigailah.", "no": 13},
{"ar": "وَلَا تُطِعْ مِنْهُمَا خَصْمًا وَلَا حَكَمًا ۞ فَأَنْتَ تَعْرِفُ كَيْدَ الْخَصْمِ وَالْحَكَمِ", "lt": "Wa lâ tuṭi‘ minhumâ khashman wa lâ ḥakaman ۞ fa anta ta‘rifu kaidal-khashmi wal-ḥakami", "id": "Janganlah engkau menaati keduanya, baik sebagai lawan maupun sebagai hakim, karena engkau tahu tipu daya lawan dan hakim (yang curang).", "no": 14},
{"ar": "أَسْتَغْفِرُ اللهَ مِنْ قَوْلٍ بِلَا عَمَلٍ ۞ لَقَدْ نَسَبْتُ بِهِ نَسْلًا لِذِيْ عُقُمِ", "lt": "Astaghfirullâha min qaulin bilâ ‘amalin ۞ laqad nasabtu bihî naslan lidzî ‘uqumi", "id": "Aku memohon ampun kepada Allah dari ucapan tanpa amal; sungguh dengan itu aku telah menisbatkan keturunan kepada orang yang mandul.", "no": 15},
{"ar": "أَمَرْتُكَ الْخَيْرَ لٰكِنْ مَا ائْتَمَرْتُ بِهِ ۞ وَمَا اسْتَقَمْتُ فَمَا قَوْلِيْ لَكَ اسْتَقِمِ", "lt": "Amartukal-khaira lâkin ma'tamartu bihî ۞ wa mas-taqamtu famâ qaulî lakas-taqimi", "id": "Aku memerintahkanmu berbuat baik, tetapi aku sendiri tidak melakukannya; aku tidak istiqamah, lalu apa artinya ucapanku kepadamu: \"Istiqamahlah\"?", "no": 16},
{"ar": "وَلَا تَزَوَّدْتُ قَبْلَ الْمَوْتِ نَافِلَةً ۞ وَلَمْ أُصَلِّ سِوَى فَرْضٍ وَلَمْ أَصُمِ", "lt": "Wa lâ tazawwadtu qablal-mauti nâfilatan ۞ wa lam ushalli siwâ fardlin wa lam ashumi", "id": "Aku tidak berbekal amalan sunnah sebelum mati; aku tidak shalat selain yang fardhu dan tidak berpuasa (sunnah).", "no": 17}]},
{judul:"Fasal 3: Pujian kepada Nabi",isi:[
{"ar": "ظَلَمْتُ سُنَّةَ مَنْ أَحْيَا الظَّلَامَ إِلَى ۞ أَنِ اشْتَكَتْ قَدَمَاهُ الضُّرَّ مِنْ وَرَمِ", "lt": "Dhalamtu sunnata man aḥyadh-dhalâma ilâ ۞ anisy-takat qadamâhudl-dlurra min warami", "id": "Aku telah menzalimi sunnah (Nabi) yang menghidupkan malam (dengan ibadah) hingga kedua kakinya mengeluh sakit karena bengkak.", "no": 1},
{"ar": "وَشَدَّ مِنْ سَغَبٍ أَحْشَاءَهُ وَطَوَى ۞ تَحْتَ الْحِجَارَةِ كَشْحًا مُتْرَفَ الْأَدَمِ", "lt": "Wa syadda min saghabin aḥsyâ'ahû wa ṭawâ ۞ taḥtal-ḥijârati kasyḥan mutrafal-adami", "id": "Beliau mengikat perutnya karena lapar, dan menyembunyikan di bawah batu (ganjal perut) pinggangnya yang berkulit halus.", "no": 2},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 3},
{"ar": "وَرَاوَدَتْهُ الْجِبَالُ الشُّمُّ مِنْ ذَهَبٍ ۞ عَنْ نَفْسِهِ فَأَرَاهَا أَيَّمَا شَمَمِ", "lt": "Wa râwadat-hul-jibâlusy-syummu min dzahabin ۞ ‘an nafsihî fa arâhâ ayyamâ syamami", "id": "Gunung-gunung yang tinggi menawarkan diri menjadi emas untuknya, namun beliau menunjukkan kepadanya keengganan yang luar biasa.", "no": 4},
{"ar": "وَأَكَّدَتْ زُهْدَهُ فِيْهَا ضَرُوْرَتُهُ ۞ إِنَّ الضَّرُوْرَةَ لَا تَعْدُوْ عَلَى الْعِصَمِ", "lt": "Wa akkadat zuhdahû fîhâ dlarûratuhû ۞ innadl-dlarûrata lâ ta‘dû ‘alal-‘ishami", "id": "Kebutuhannya (yang mendesak) justru menguatkan kezuhudannya terhadap dunia, karena kebutuhan tidak dapat mengalahkan orang yang terjaga (dari dosa).", "no": 5},
{"ar": "وَكَيْفَ تَدْعُوْ إِلَى الدُّنْيَا ضَرُوْرَةُ مَنْ ۞ لَوْلَاهُ لَمْ تَخْرُجِ الدُّنْيَا مِنَ الْعَدَمِ", "lt": "Wa kaifa tad‘û ilad-dunyâ dlarûratu man ۞ laulâhu lam takhrujid-dunyâ minal-‘adami", "id": "Bagaimana mungkin kebutuhan dapat menarik kepada dunia seseorang yang, seandainya bukan karena dia, dunia tidak akan keluar dari ketiadaan?", "no": 6},
{"ar": "مُحَمَّدٌ سَيِّدُ الْكَوْنَيْنِ وَالثَّقَلَيْنِ ۞ وَالْفَرِيْقَيْنِ مِنْ عُرْبٍ وَمِنْ عَجَمِ", "lt": "Muḥammadun sayyidul-kaunaini wats-tsaqalain ۞ wal-farîqaini min ‘urbin wa min ‘ajami", "id": "Muhammad adalah pemimpin dua alam (dunia dan akhirat), dua golongan (manusia dan jin), dan dua bangsa, Arab dan non-Arab.", "no": 7},
{"ar": "نَبِيُّنَا الْآمِرُ النَّاهِيْ فَلَا أَحَدٌ ۞ أَبَرَّ فِيْ قَوْلِ لَا مِنْهُ وَلَا نَعَمِ", "lt": "Nabiyyunal-âmirun-nâhî falâ aḥadun ۞ abarra fî qauli lâ minhu wa lâ na‘ami", "id": "Nabi kita yang memerintah dan melarang; tak seorang pun lebih jujur daripada beliau dalam mengucapkan \"tidak\" maupun \"ya\".", "no": 8},
{"ar": "هُوَ الْحَبِيْبُ الَّذِيْ تُرْجَى شَفَاعَتُهُ ۞ لِكُلِّ هَوْلٍ مِنَ الْأَهْوَالِ مُقْتَحِمِ", "lt": "Huwal-ḥabîbul-ladzî turjâ syafâ‘atuhû ۞ likulli haulin minal-ahwâli muqtaḥimi", "id": "Dialah kekasih yang syafaatnya diharapkan untuk (menghadapi) setiap kengerian yang menerjang.", "no": 9},
{"ar": "دَعَا إِلَى اللهِ فَالْمُسْتَمْسِكُوْنَ بِهِ ۞ مُسْتَمْسِكُوْنَ بِحَبْلٍ غَيْرِ مُنْفَصِمِ", "lt": "Da‘â ilallâhi fal-mustamsikûna bihî ۞ mustamsikûna biḥablin ghairi munfashimi", "id": "Beliau mengajak kepada Allah; maka orang-orang yang berpegang kepadanya berarti berpegang pada tali yang tidak akan putus.", "no": 10},
{"ar": "فَاقَ النَّبِيِّيْنَ فِيْ خَلْقٍ وَفِيْ خُلُقٍ ۞ وَلَمْ يُدَانُوْهُ فِيْ عِلْمٍ وَلَا كَرَمِ", "lt": "Fâqan-nabiyyîna fî khalqin wa fî khuluqin ۞ wa lam yudânûhu fî ‘ilmin wa lâ karami", "id": "Beliau mengungguli para nabi dalam rupa dan akhlak, dan mereka tidak dapat menyamainya dalam ilmu maupun kemuliaan.", "no": 11},
{"ar": "وَكُلُّهُمْ مِنْ رَسُوْلِ اللهِ مُلْتَمِسٌ ۞ غَرْفًا مِنَ الْبَحْرِ أَوْ رَشْفًا مِنَ الدِّيَمِ", "lt": "Wa kulluhum min rasûlillâhi multamisun ۞ gharfan minal-baḥri au rasyfan minad-diyami", "id": "Mereka semua memohon dari Rasulullah seciduk dari lautan (ilmunya) atau setetes dari hujan (kemurahannya).", "no": 12},
{"ar": "وَوَاقِفُوْنَ لَدَيْهِ عِنْدَ حَدِّهِمِ ۞ مِنْ نُقْطَةِ الْعِلْمِ أَوْ مِنْ شَكْلَةِ الْحِكَمِ", "lt": "Wa wâqifûna ladaihi ‘inda ḥaddihimi ۞ min nuqṭatil-‘ilmi au min syaklatil-ḥikami", "id": "Mereka berdiri di hadapan beliau sesuai batas kedudukan mereka, (bagaikan) titik dari ilmunya atau harakat dari hikmah-hikmahnya.", "no": 13},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 14},
{"ar": "فَهْوَ الَّذِيْ تَمَّ مَعْنَاهُ وَصُوْرَتُهُ ۞ ثُمَّ اصْطَفَاهُ حَبِيْبًا بَارِئُ النَّسَمِ", "lt": "Fahwal-ladzî tamma ma‘nâhu wa shûratuhû ۞ tsummash-ṭafâhu ḥabîban bâri'un-nasami", "id": "Dialah yang sempurna batin dan lahirnya, kemudian Pencipta seluruh jiwa memilihnya sebagai kekasih.", "no": 15},
{"ar": "مُنَزَّهٌ عَنْ شَرِيْكٍ فِيْ مَحَاسِنِهِ ۞ فَجَوْهَرُ الْحُسْنِ فِيْهِ غَيْرُ مُنْقَسِمِ", "lt": "Munazzahun ‘an syarîkin fî maḥâsinihî ۞ fajauharul-ḥusni fîhi ghairu munqasimi", "id": "Beliau tersucikan dari adanya sekutu dalam kebaikan-kebaikannya, maka permata keindahan pada dirinya tidak terbagi-bagi.", "no": 16},
{"ar": "دَعْ مَا ادَّعَتْهُ النَّصَارَى فِيْ نَبِيِّهِمِ ۞ وَاحْكُمْ بِمَا شِئْتَ مَدْحًا فِيْهِ وَاحْتَكِمِ", "lt": "Da‘ mad-da‘at-hun-nashârâ fî nabiyyihimi ۞ waḥkum bimâ syi'ta madḥan fîhi waḥtakimi", "id": "Tinggalkanlah apa yang didakwakan kaum Nasrani terhadap nabi mereka, lalu tetapkanlah pujian apa saja yang engkau kehendaki tentang beliau, dan berhukumlah.", "no": 17},
{"ar": "وَانْسُبْ إِلَى ذَاتِهِ مَا شِئْتَ مِنْ شَرَفٍ ۞ وَانْسُبْ إِلَى قَدْرِهِ مَا شِئْتَ مِنْ عِظَمِ", "lt": "Wansub ilâ dzâtihî mâ syi'ta min syarafin ۞ wansub ilâ qadrihî mâ syi'ta min ‘idhami", "id": "Nisbatkanlah kepada pribadinya kemuliaan apa saja yang engkau kehendaki, dan nisbatkanlah kepada kedudukannya keagungan apa saja yang engkau kehendaki.", "no": 18},
{"ar": "فَإِنَّ فَضْلَ رَسُوْلِ اللهِ لَيْسَ لَهُ ۞ حَدٌّ فَيُعْرِبَ عَنْهُ نَاطِقٌ بِفَمِ", "lt": "Fa inna fadlla rasûlillâhi laisa lahû ۞ ḥaddun fayu‘riba ‘anhu nâṭiqun bifami", "id": "Sesungguhnya keutamaan Rasulullah tidak memiliki batas, sehingga (tidak mungkin) seorang pembicara dapat mengungkapkannya dengan mulutnya.", "no": 19},
{"ar": "لَوْ نَاسَبَتْ قَدْرَهُ آيَاتُهُ عِظَمًا ۞ أَحْيَا اسْمُهُ حِيْنَ يُدْعَى دَارِسَ الرِّمَمِ", "lt": "Lau nâsabat qadrahû âyâtuhû ‘idhaman ۞ aḥyas-muhû ḥîna yud‘â dârisar-rimami", "id": "Seandainya mukjizat-mukjizatnya sebanding dengan keagungan derajatnya, niscaya namanya, ketika disebut, dapat menghidupkan tulang-belulang yang telah hancur.", "no": 20},
{"ar": "لَمْ يَمْتَحِنَّا بِمَا تَعْيَا الْعُقُوْلُ بِهِ ۞ حِرْصًا عَلَيْنَا فَلَمْ نَرْتَبْ وَلَمْ نَهِمِ", "lt": "Lam yamtaḥinnâ bimâ ta‘yal-‘uqûlu bihî ۞ ḥirshan ‘alainâ falam nartab wa lam nahimi", "id": "Beliau tidak menguji kita dengan sesuatu yang tak mampu dicerna akal, karena kasih sayangnya kepada kita, sehingga kita tidak ragu dan tidak bingung.", "no": 21},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 22},
{"ar": "أَعْيَا الْوَرَى فَهْمُ مَعْنَاهُ فَلَيْسَ يُرَى ۞ فِي الْقُرْبِ وَالْبُعْدِ فِيْهِ غَيْرُ مُنْفَحِمِ", "lt": "A‘yal-warâ fahmu ma‘nâhu falaisa yurâ ۞ fil-qurbi wal-bu‘di fîhi ghairu munfaḥimi", "id": "Seluruh makhluk tak mampu memahami hakikatnya; tidak terlihat seorang pun, baik yang dekat maupun yang jauh, kecuali kehabisan kata tentangnya.", "no": 23},
{"ar": "كَالشَّمْسِ تَظْهَرُ لِلْعَيْنَيْنِ مِنْ بُعُدٍ ۞ صَغِيْرَةً وَتُكِلُّ الطَّرْفَ مِنْ أَمَمِ", "lt": "Kasy-syamsi tadh-haru lil-‘ainaini min bu‘udin ۞ shaghîratan wa tukilluṭ-ṭarfa min amami", "id": "Bagaikan matahari, dari jauh tampak kecil oleh kedua mata, namun bila didekati ia melelahkan pandangan.", "no": 24},
{"ar": "وَكَيْفَ يُدْرِكُ فِي الدُّنْيَا حَقِيْقَتَهُ ۞ قَوْمٌ نِيَامٌ تَسَلَّوْا عَنْهُ بِالْحُلُمِ", "lt": "Wa kaifa yudriku fid-dunyâ ḥaqîqatahû ۞ qaumun niyâmun tasallau ‘anhu bil-ḥulumi", "id": "Bagaimana mungkin di dunia ini dapat memahami hakikatnya suatu kaum yang tertidur, yang menghibur diri tentangnya dengan mimpi?", "no": 25},
{"ar": "فَمَبْلَغُ الْعِلْمِ فِيْهِ أَنَّهُ بَشَرٌ ۞ وَأَنَّهُ خَيْرُ خَلْقِ اللهِ كُلِّهِمِ", "lt": "Famablaghul-‘ilmi fîhi annahû basyarun ۞ wa annahû khairu khalqillâhi kullihimi", "id": "Puncak pengetahuan tentangnya adalah bahwa beliau seorang manusia, dan bahwa beliau sebaik-baik seluruh makhluk Allah.", "no": 26},
{"ar": "وَكُلُّ آيٍ أَتَى الرُّسْلُ الْكِرَامُ بِهَا ۞ فَإِنَّمَا اتَّصَلَتْ مِنْ نُوْرِهِ بِهِمِ", "lt": "Wa kullu âyin atar-rusulul-kirâmu bihâ ۞ fa innamat-tashalat min nûrihî bihimi", "id": "Setiap mukjizat yang dibawa oleh para rasul yang mulia, sesungguhnya bersambung kepada mereka dari cahayanya.", "no": 27},
{"ar": "فَإِنَّهُ شَمْسُ فَضْلٍ هُمْ كَوَاكِبُهَا ۞ يُظْهِرْنَ أَنْوَارَهَا لِلنَّاسِ فِي الظُّلَمِ", "lt": "Fa innahû syamsu fadllin hum kawâkibuhâ ۞ yudh-hirna anwârahâ lin-nâsi fidh-dhulami", "id": "Sesungguhnya beliau adalah matahari keutamaan dan mereka adalah bintang-bintangnya, yang menampakkan cahayanya kepada manusia di dalam kegelapan.", "no": 28},
{"ar": "أَكْرِمْ بِخَلْقِ نَبِيٍّ زَانَهُ خُلُقٌ ۞ بِالْحُسْنِ مُشْتَمِلٍ بِالْبِشْرِ مُتَّسِمِ", "lt": "Akrim bikhalqi nabiyyin zânahû khuluqun ۞ bil-ḥusni mustamilin bil-bisyri muttasimi", "id": "Betapa mulia rupa Nabi yang dihiasi akhlak, yang diliputi keindahan dan ditandai dengan wajah yang berseri.", "no": 29},
{"ar": "كَالزَّهْرِ فِيْ تَرَفٍ وَالْبَدْرِ فِيْ شَرَفٍ ۞ وَالْبَحْرِ فِيْ كَرَمٍ وَالدَّهْرِ فِيْ هِمَمِ", "lt": "Kaz-zahri fî tarafin wal-badri fî syarafin ۞ wal-baḥri fî karamin wad-dahri fî himami", "id": "Bagaikan bunga dalam kelembutan, purnama dalam kemuliaan, lautan dalam kedermawanan, dan masa dalam tekad.", "no": 30},
{"ar": "كَأَنَّهُ وَهْوَ فَرْدٌ مِنْ جَلَالَتِهِ ۞ فِيْ عَسْكَرٍ حِيْنَ تَلْقَاهُ وَفِيْ حَشَمِ", "lt": "Ka'annahû wahwa fardun min jalâlatihî ۞ fî ‘askarin ḥîna talqâhu wa fî ḥasyami", "id": "Meskipun beliau sendirian, karena keagungannya seakan-akan beliau berada di tengah pasukan dan para pengiring ketika engkau menjumpainya.", "no": 31},
{"ar": "كَأَنَّمَا اللُّؤْلُؤُ الْمَكْنُوْنُ فِيْ صَدَفٍ ۞ مِنْ مَعْدِنَيْ مَنْطِقٍ مِنْهُ وَمُبْتَسَمِ", "lt": "Ka'annamal-lu'lu'ul-maknûnu fî shadafin ۞ min ma‘danai manṭiqin minhu wa mubtasami", "id": "Seakan-akan mutiara yang tersimpan dalam kerang berasal dari dua sumber, yaitu tutur katanya dan senyumannya.", "no": 32},
{"ar": "لَا طِيْبَ يَعْدِلُ تُرْبًا ضَمَّ أَعْظُمَهُ ۞ طُوْبَى لِمُنْتَشِقٍ مِنْهُ وَمُلْتَثِمِ", "lt": "Lâ ṭîba ya‘dilu turban dlamma a‘dhumahû ۞ ṭûbâ limuntasyiqin minhu wa multatsimi", "id": "Tidak ada wewangian yang menyamai tanah yang mendekap tulang-tulangnya; beruntunglah orang yang menghirup dan menciumnya.", "no": 33}]},
{judul:"Fasal 4: Kelahiran Nabi (Mahallul Qiyam)",isi:[
{"ar": "أَبَانَ مَوْلِدُهُ عَنْ طِيْبِ عُنْصُرِهِ ۞ يَا طِيْبَ مُبْتَدَإٍ مِنْهُ وَمُخْتَتَمِ", "lt": "Abâna mauliduhû ‘an ṭîbi ‘unshurihî ۞ yâ ṭîba mubtada'in minhu wa mukhtatami", "id": "Kelahirannya menampakkan kesucian asal-usulnya; alangkah harumnya permulaan dan penghabisannya.", "no": 1},
{"ar": "يَوْمٌ تَفَرَّسَ فِيْهِ الْفُرْسُ أَنَّهُمُ ۞ قَدْ أُنْذِرُوْا بِحُلُوْلِ الْبُؤْسِ وَالنِّقَمِ", "lt": "Yaumun tafarrasa fîhil-fursu annahumu ۞ qad undzirû biḥulûlil-bu'si wan-niqami", "id": "Itulah hari ketika bangsa Persia merasakan firasat bahwa mereka telah diperingatkan akan datangnya kesengsaraan dan siksaan.", "no": 2},
{"ar": "وَبَاتَ إِيْوَانُ كِسْرَى وَهْوَ مُنْصَدِعٌ ۞ كَشَمْلِ أَصْحَابِ كِسْرَى غَيْرَ مُلْتَئِمِ", "lt": "Wa bâta îwânu kisrâ wahwa munshadi‘un ۞ kasyamli ash-ḥâbi kisrâ ghaira multa'imi", "id": "Malam itu istana Kisra retak, sebagaimana persatuan para pengikut Kisra tercerai-berai tak dapat dipersatukan lagi.", "no": 3},
{"ar": "وَالنَّارُ خَامِدَةُ الْأَنْفَاسِ مِنْ أَسَفٍ ۞ عَلَيْهِ وَالنَّهْرُ سَاهِي الْعَيْنِ مِنْ سَدَمِ", "lt": "Wan-nâru khâmidatul-anfâsi min asafin ۞ ‘alaihi wan-nahru sâhil-‘aini min sadami", "id": "Api (sesembahan Persia) padam nyalanya karena sedih atas (kelahiran)nya, dan sungai (Eufrat) terhenti alirannya karena duka.", "no": 4},
{"ar": "وَسَاءَ سَاوَةَ أَنْ غَاضَتْ بُحَيْرَتُهَا ۞ وَرُدَّ وَارِدُهَا بِالْغَيْظِ حِيْنَ ظَمِيْ", "lt": "Wa sâ'a sâwata an ghâdlat buḥairatuhâ ۞ wa rudda wâriduhâ bil-ghaidhi ḥîna dhamî", "id": "Penduduk Sawah bersedih karena danaunya mengering, dan orang yang datang mengambil air pulang dengan kecewa ketika ia kehausan.", "no": 5},
{"ar": "كَأَنَّ بِالنَّارِ مَا بِالْمَاءِ مِنْ بَلَلٍ ۞ حُزْنًا وَبِالْمَاءِ مَا بِالنَّارِ مِنْ ضَرَمِ", "lt": "Ka'anna bin-nâri mâ bil-mâ'i min balalin ۞ ḥuznan wa bil-mâ'i mâ bin-nâri min dlarami", "id": "Seakan-akan api menjadi basah seperti air karena sedih, dan air menjadi panas membara seperti api.", "no": 6},
{"ar": "وَالْجِنُّ تَهْتِفُ وَالْأَنْوَارُ سَاطِعَةٌ ۞ وَالْحَقُّ يَظْهَرُ مِنْ مَعْنًى وَمِنْ كَلِمِ", "lt": "Wal-jinnu tahtifu wal-anwâru sâṭi‘atun ۞ wal-ḥaqqu yadh-haru min ma‘nan wa min kalimi", "id": "Jin-jin berseru, cahaya-cahaya memancar, dan kebenaran tampak, baik dalam makna maupun ucapan.", "no": 7},
{"ar": "عَمُوْا وَصَمُّوْا فَإِعْلَانُ الْبَشَائِرِ لَمْ ۞ تُسْمَعْ وَبَارِقَةُ الْإِنْذَارِ لَمْ تُشَمِ", "lt": "‘Amû wa shammû fa i‘lânul-basyâ'iri lam ۞ tusma‘ wa bâriqatul-indzâri lam tusyami", "id": "Mereka (orang-orang kafir) buta dan tuli, sehingga pengumuman kabar gembira tidak terdengar dan kilat peringatan tidak terlihat.", "no": 8},
{"ar": "مِنْ بَعْدِ مَا أَخْبَرَ الْأَقْوَامَ كَاهِنُهُمْ ۞ بِأَنَّ دِيْنَهُمُ الْمُعْوَجَّ لَمْ يَقُمِ", "lt": "Min ba‘di mâ akhbaral-aqwâma kâhinuhum ۞ bi'anna dînahumul-mu‘wajja lam yaqumi", "id": "(Padahal itu terjadi) setelah dukun-dukun mereka mengabarkan kepada kaumnya bahwa agama mereka yang bengkok tidak akan tegak lagi.", "no": 9},
{"ar": "وَبَعْدَ مَا عَايَنُوْا فِي الْأُفْقِ مِنْ شُهُبٍ ۞ مُنْقَضَّةٍ وَفْقَ مَا فِي الْأَرْضِ مِنْ صَنَمِ", "lt": "Wa ba‘da mâ ‘âyanû fil-ufqi min syuhubin ۞ munqadldlatin wafqa mâ fil-ardli min shanami", "id": "Dan setelah mereka menyaksikan di cakrawala bintang-bintang berjatuhan, sebagaimana berhala-berhala di bumi berjatuhan.", "no": 10},
{"ar": "حَتَّى غَدَا عَنْ طَرِيْقِ الْوَحْيِ مُنْهَزِمٌ ۞ مِنَ الشَّيَاطِيْنِ يَقْفُوْ إِثْرَ مُنْهَزِمِ", "lt": "Ḥattâ ghadâ ‘an ṭarîqil-waḥyi munhazimun ۞ minasy-syayâṭîni yaqfû itsra munhazimi", "id": "Hingga setan-setan lari tunggang langgang dari jalan wahyu, yang satu mengikuti jejak yang lain.", "no": 11},
{"ar": "كَأَنَّهُمْ هَرَبًا أَبْطَالُ أَبْرَهَةٍ ۞ أَوْ عَسْكَرٌ بِالْحَصَى مِنْ رَاحَتَيْهِ رُمِيْ", "lt": "Ka'annahum haraban abṭâlu abrahatin ۞ au ‘askarun bil-ḥashâ min râḥataihi rumî", "id": "Seakan-akan dalam pelarian itu mereka adalah pasukan Abrahah, atau tentara yang dilempari kerikil dari kedua telapak tangan beliau.", "no": 12},
{"ar": "نَبْذًا بِهِ بَعْدَ تَسْبِيْحٍ بِبَطْنِهِمَا ۞ نَبْذَ الْمُسَبِّحِ مِنْ أَحْشَاءِ مُلْتَقِمِ", "lt": "Nabdzan bihî ba‘da tasbîḥin bibaṭnihimâ ۞ nabdzal-musabbiḥi min aḥsyâ'i multaqimi", "id": "(Kerikil itu) dilemparkan setelah bertasbih di kedua telapak tangannya, sebagaimana (Nabi Yunus) yang bertasbih dilemparkan dari perut (ikan) yang menelannya.", "no": 13},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 14}]},
{judul:"Fasal 5: Mukjizat Nabi",isi:[
{"ar": "جَاءَتْ لِدَعْوَتِهِ الْأَشْجَارُ سَاجِدَةً ۞ تَمْشِيْ إِلَيْهِ عَلَى سَاقٍ بِلَا قَدَمِ", "lt": "Jâ'at lida‘watihil-asyjâru sâjidatan ۞ tamsyî ilaihi ‘alâ sâqin bilâ qadami", "id": "Pohon-pohon datang memenuhi panggilannya dalam keadaan bersujud, berjalan kepadanya dengan batang tanpa kaki.", "no": 1},
{"ar": "كَأَنَّمَا سَطَرَتْ سَطْرًا لِمَا كَتَبَتْ ۞ فُرُوْعُهَا مِنْ بَدِيْعِ الْخَطِّ فِي اللَّقَمِ", "lt": "Ka'annamâ saṭarat saṭran limâ katabat ۞ furû‘uhâ min badî‘il-khaṭṭi fil-laqami", "id": "Seakan-akan pohon-pohon itu menggoreskan garis lurus untuk apa yang ditulis oleh dahan-dahannya, berupa tulisan indah di tengah jalan.", "no": 2},
{"ar": "مِثْلَ الْغَمَامَةِ أَنَّى سَارَ سَائِرَةً ۞ تَقِيْهِ حَرَّ وَطِيْسٍ لِلْهَجِيْرِ حَمِيْ", "lt": "Mitslal-ghamâmati annâ sâra sâ'iratan ۞ taqîhi ḥarra waṭîsin lil-hajîri ḥamî", "id": "Seperti awan yang ke mana pun beliau pergi selalu menyertainya, melindunginya dari panasnya terik siang yang membakar.", "no": 3},
{"ar": "أَقْسَمْتُ بِالْقَمَرِ الْمُنْشَقِّ إِنَّ لَهُ ۞ مِنْ قَلْبِهِ نِسْبَةً مَبْرُوْرَةَ الْقَسَمِ", "lt": "Aqsamtu bil-qamaril-munsyaqqi inna lahû ۞ min qalbihî nisbatan mabrûratal-qasami", "id": "Aku bersumpah demi bulan yang terbelah, sesungguhnya bulan itu memiliki hubungan dengan hati beliau (yang dibelah), sumpah yang benar.", "no": 4},
{"ar": "وَمَا حَوَى الْغَارُ مِنْ خَيْرٍ وَمِنْ كَرَمٍ ۞ وَكُلُّ طَرْفٍ مِنَ الْكُفَّارِ عَنْهُ عَمِيْ", "lt": "Wa mâ ḥawal-ghâru min khairin wa min karamin ۞ wa kullu ṭarfin minal-kuffâri ‘anhu ‘amî", "id": "(Aku bersumpah) demi kebaikan dan kemuliaan yang ada di dalam gua (Tsur), sementara setiap mata orang kafir buta untuk melihatnya.", "no": 5},
{"ar": "فَالصِّدْقُ فِي الْغَارِ وَالصِّدِّيْقُ لَمْ يَرِمَا ۞ وَهُمْ يَقُوْلُوْنَ مَا بِالْغَارِ مِنْ أَرِمِ", "lt": "Fash-shidqu fil-ghâri wash-shiddîqu lam yarimâ ۞ wa hum yaqûlûna mâ bil-ghâri min arimi", "id": "Ash-Shidq (Nabi) dan Ash-Shiddiq (Abu Bakar) tetap berada di dalam gua tanpa beranjak, sementara mereka (orang kafir) berkata: Tidak ada seorang pun di dalam gua.", "no": 6},
{"ar": "ظَنُّوا الْحَمَامَ وَظَنُّوا الْعَنْكَبُوْتَ عَلَى ۞ خَيْرِ الْبَرِيَّةِ لَمْ تَنْسُجْ وَلَمْ تَحُمِ", "lt": "Dhannul-ḥamâma wa dhannul-‘ankabûta ‘alâ ۞ khairil-bariyyati lam tansuj wa lam taḥumi", "id": "Mereka mengira burung merpati tidak akan bertelur dan laba-laba tidak akan bersarang di atas (gua tempat) sebaik-baik makhluk.", "no": 7},
{"ar": "وِقَايَةُ اللهِ أَغْنَتْ عَنْ مُضَاعَفَةٍ ۞ مِنَ الدُّرُوْعِ وَعَنْ عَالٍ مِنَ الْأُطُمِ", "lt": "Wiqâyatullâhi aghnat ‘an mudlâ‘afatin ۞ minad-durû‘i wa ‘an ‘âlin minal-uṭumi", "id": "Perlindungan Allah sudah mencukupi, tidak perlu baju besi berlapis-lapis dan benteng yang tinggi.", "no": 8},
{"ar": "مَا سَامَنِي الدَّهْرُ ضَيْمًا وَاسْتَجَرْتُ بِهِ ۞ إِلَّا وَنِلْتُ جِوَارًا مِنْهُ لَمْ يُضَمِ", "lt": "Mâ sâmaniyad-dahru dlaiman wastajartu bihî ۞ illâ wa niltu jiwâran minhu lam yudlami", "id": "Tidaklah zaman menimpakan kezaliman kepadaku lalu aku berlindung kepadanya, kecuali aku mendapatkan perlindungan darinya yang tidak teraniaya.", "no": 9},
{"ar": "وَلَا الْتَمَسْتُ غِنَى الدَّارَيْنِ مِنْ يَدِهِ ۞ إِلَّا اسْتَلَمْتُ النَّدَى مِنْ خَيْرِ مُسْتَلَمِ", "lt": "Wa lal-tamastu ghinad-dâraini min yadihî ۞ illas-talamtun-nadâ min khairi mustalami", "id": "Dan tidaklah aku memohon kekayaan dunia dan akhirat dari tangannya, kecuali aku menerima kemurahan dari sebaik-baik pemberi.", "no": 10},
{"ar": "لَا تُنْكِرِ الْوَحْيَ مِنْ رُؤْيَاهُ إِنَّ لَهُ ۞ قَلْبًا إِذَا نَامَتِ الْعَيْنَانِ لَمْ يَنَمِ", "lt": "Lâ tunkiril-waḥya min ru'yâhu inna lahû ۞ qalban idzâ nâmatil-‘ainâni lam yanami", "id": "Janganlah engkau mengingkari wahyu (yang datang) melalui mimpinya, sesungguhnya beliau memiliki hati yang tidak tidur meskipun kedua matanya tidur.", "no": 11},
{"ar": "وَذَاكَ حِيْنَ بُلُوْغٍ مِنْ نُبُوَّتِهِ ۞ فَلَيْسَ يُنْكَرُ فِيْهِ حَالُ مُحْتَلِمِ", "lt": "Wa dzâka ḥîna bulûghin min nubuwwatihî ۞ falaisa yunkaru fîhi ḥâlu muḥtalimi", "id": "Hal itu terjadi saat beliau mencapai usia kenabian (empat puluh tahun), maka tidaklah diingkari keadaan (mimpi) seorang yang telah dewasa.", "no": 12},
{"ar": "تَبَارَكَ اللهُ مَا وَحْيٌ بِمُكْتَسَبٍ ۞ وَلَا نَبِيٌّ عَلَى غَيْبٍ بِمُتَّهَمِ", "lt": "Tabârakallâhu mâ waḥyun bimuktasabin ۞ wa lâ nabiyyun ‘alâ ghaibin bimuttahami", "id": "Mahasuci Allah, wahyu itu bukanlah sesuatu yang dapat diusahakan, dan tidak ada nabi yang patut dicurigai dalam (mengabarkan) perkara gaib.", "no": 13},
{"ar": "كَمْ أَبْرَأَتْ وَصِبًا بِاللَّمْسِ رَاحَتُهُ ۞ وَأَطْلَقَتْ أَرِبًا مِنْ رِبْقَةِ اللَّمَمِ", "lt": "Kam abra'at washiban bil-lamsi râḥatuhû ۞ wa aṭlaqat ariban min ribqatil-lamami", "id": "Betapa banyak orang sakit yang sembuh dengan usapan telapak tangannya, dan betapa banyak orang yang terbebas dari belenggu gila.", "no": 14},
{"ar": "وَأَحْيَتِ السَّنَةَ الشَّهْبَاءَ دَعْوَتُهُ ۞ حَتَّى حَكَتْ غُرَّةً فِي الْأَعْصُرِ الدُّهُمِ", "lt": "Wa aḥyatis-sanatasy-syahbâ'a da‘watuhû ۞ ḥattâ ḥakat ghurratan fil-a‘shurid-duhumi", "id": "Doanya menghidupkan tahun yang kering kerontang, hingga tahun itu bagaikan cahaya putih di tengah masa-masa yang kelam.", "no": 15},
{"ar": "بِعَارِضٍ جَادَ أَوْ خِلْتَ الْبِطَاحَ بِهَا ۞ سَيْبٌ مِنَ الْيَمِّ أَوْ سَيْلٌ مِنَ الْعَرِمِ", "lt": "Bi‘âridlin jâda au khiltal-biṭâḥa bihâ ۞ saibun minal-yammi au sailun minal-‘arimi", "id": "Dengan awan yang menurunkan hujan lebat, hingga engkau sangka lembah-lembah itu dilanda luapan laut atau banjir bendungan 'Arim.", "no": 16},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 17},
{"ar": "دَعْنِيْ وَوَصْفِيْ آيَاتٍ لَهُ ظَهَرَتْ ۞ ظُهُوْرَ نَارِ الْقِرَى لَيْلًا عَلَى عَلَمِ", "lt": "Da‘nî wa washfî âyâtin lahû dhaharat ۞ dhuhûra nâril-qirâ lailan ‘alâ ‘alami", "id": "Biarkanlah aku menyifati tanda-tanda kebesarannya yang tampak, bagaikan tampaknya api jamuan tamu di malam hari di atas gunung.", "no": 18}]},
{judul:"Fasal 6: Keagungan Al-Qur'an",isi:[
{"ar": "فَالدُّرُّ يَزْدَادُ حُسْنًا وَهْوَ مُنْتَظِمٌ ۞ وَلَيْسَ يَنْقُصُ قَدْرًا غَيْرَ مُنْتَظِمِ", "lt": "Fad-durru yazdâdu ḥusnan wahwa muntadhimun ۞ wa laisa yanqushu qadran ghaira muntadhimi", "id": "Mutiara bertambah indah bila tersusun rapi, namun nilainya tidaklah berkurang meski tidak tersusun.", "no": 1},
{"ar": "فَمَا تَطَاوُلُ آمَالِ الْمَدِيْحِ إِلَى ۞ مَا فِيْهِ مِنْ كَرَمِ الْأَخْلَاقِ وَالشِّيَمِ", "lt": "Famâ taṭâwulu âmâlil-madîḥi ilâ ۞ mâ fîhi min karamil-akhlâqi wasy-syiyami", "id": "Maka bagaimana mungkin harapan para pemuji dapat menjangkau kemuliaan akhlak dan budi pekerti yang ada pada dirinya?", "no": 2},
{"ar": "آيَاتُ حَقٍّ مِنَ الرَّحْمٰنِ مُحْدَثَةٌ ۞ قَدِيْمَةٌ صِفَةُ الْمَوْصُوْفِ بِالْقِدَمِ", "lt": "Âyâtu ḥaqqin minar-raḥmâni muḥdatsatun ۞ qadîmatun shifatul-maushûfi bil-qidami", "id": "(Al-Qur'an adalah) ayat-ayat kebenaran dari Ar-Rahman, yang baru (dalam turunnya), namun qadim sebagai sifat Dzat yang bersifat qadim.", "no": 3},
{"ar": "لَمْ تَقْتَرِنْ بِزَمَانٍ وَهْيَ تُخْبِرُنَا ۞ عَنِ الْمَعَادِ وَعَنْ عَادٍ وَعَنْ إِرَمِ", "lt": "Lam taqtarin bizamânin wahya tukhbirunâ ۞ ‘anil-ma‘âdi wa ‘an ‘âdin wa ‘an irami", "id": "Ia tidak terikat dengan zaman, sedang ia mengabarkan kepada kita tentang hari kebangkitan, kaum 'Ad, dan kota Iram.", "no": 4},
{"ar": "دَامَتْ لَدَيْنَا فَفَاقَتْ كُلَّ مُعْجِزَةٍ ۞ مِنَ النَّبِيِّيْنَ إِذْ جَاءَتْ وَلَمْ تَدُمِ", "lt": "Dâmat ladainâ fafâqat kulla mu‘jizatin ۞ minan-nabiyyîna idz jâ'at wa lam tadumi", "id": "Ia kekal di tengah kita, maka ia mengungguli setiap mukjizat para nabi, karena mukjizat-mukjizat itu datang lalu tidak kekal.", "no": 5},
{"ar": "مُحَكَّمَاتٌ فَمَا تُبْقِيْنَ مِنْ شُبَهٍ ۞ لِذِيْ شِقَاقٍ وَمَا تَبْغِيْنَ مِنْ حَكَمِ", "lt": "Muḥakkamâtun famâ tubqîna min syubahin ۞ lidzî syiqâqin wa mâ tabghîna min ḥakami", "id": "Ayat-ayatnya kokoh, tidak menyisakan keraguan bagi orang yang menentang, dan tidak membutuhkan hakim (lain).", "no": 6},
{"ar": "مَا حُوْرِبَتْ قَطُّ إِلَّا عَادَ مِنْ حَرَبٍ ۞ أَعْدَى الْأَعَادِيْ إِلَيْهَا مُلْقِيَ السَّلَمِ", "lt": "Mâ ḥûribat qaṭṭu illâ ‘âda min ḥarabin ۞ a‘dal-a‘âdî ilaihâ mulqiyas-salami", "id": "Tidaklah ia ditentang sedikit pun, kecuali musuh yang paling keras kembali dari peperangan dengan menyerah kalah.", "no": 7},
{"ar": "رَدَّتْ بَلَاغَتُهَا دَعْوَى مُعَارِضِهَا ۞ رَدَّ الْغَيُوْرِ يَدَ الْجَانِيْ عَنِ الْحُرَمِ", "lt": "Raddat balâghatuhâ da‘wâ mu‘âridlihâ ۞ raddal-ghayûri yadal-jânî ‘anil-ḥurami", "id": "Kefasihannya menolak dakwaan orang yang hendak menandinginya, sebagaimana orang yang cemburu menepis tangan penjahat dari keluarganya.", "no": 8},
{"ar": "لَهَا مَعَانٍ كَمَوْجِ الْبَحْرِ فِيْ مَدَدٍ ۞ وَفَوْقَ جَوْهَرِهِ فِي الْحُسْنِ وَالْقِيَمِ", "lt": "Lahâ ma‘ânin kamaujil-baḥri fî madadin ۞ wa fauqa jauharihî fil-ḥusni wal-qiyami", "id": "Ia memiliki makna-makna yang melimpah bagaikan gelombang laut, dan melebihi mutiaranya dalam keindahan dan nilai.", "no": 9},
{"ar": "فَمَا تُعَدُّ وَلَا تُحْصَى عَجَائِبُهَا ۞ وَلَا تُسَامُ عَلَى الْإِكْثَارِ بِالسَّأَمِ", "lt": "Famâ tu‘addu wa lâ tuḥshâ ‘ajâ'ibuhâ ۞ wa lâ tusâmu ‘alal-iktsâri bis-sa'ami", "id": "Keajaiban-keajaibannya tidak terhitung dan tidak terhingga, dan tidak membosankan meskipun sering dibaca.", "no": 10},
{"ar": "قَرَّتْ بِهَا عَيْنُ قَارِيْهَا فَقُلْتُ لَهُ ۞ لَقَدْ ظَفِرْتَ بِحَبْلِ اللهِ فَاعْتَصِمِ", "lt": "Qarrat bihâ ‘ainu qârîhâ faqultu lahû ۞ laqad dhafirta biḥablillâhi fa‘tashimi", "id": "Sejuklah mata pembacanya dengannya, maka aku berkata kepadanya: Sungguh engkau telah memperoleh tali Allah, maka berpegang teguhlah.", "no": 11},
{"ar": "إِنْ تَتْلُهَا خِيْفَةً مِنْ حَرِّ نَارِ لَظَى ۞ أَطْفَأْتَ حَرَّ لَظَى مِنْ وِرْدِهَا الشَّبِمِ", "lt": "In tatluhâ khîfatan min ḥarri nâri ladhâ ۞ aṭfa'ta ḥarra ladhâ min wirdihasy-syabimi", "id": "Jika engkau membacanya karena takut akan panasnya api Neraka Ladha, niscaya engkau padamkan panasnya Ladha dengan sumbernya yang sejuk.", "no": 12},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 13},
{"ar": "كَأَنَّهَا الْحَوْضُ تَبْيَضُّ الْوُجُوْهُ بِهِ ۞ مِنَ الْعُصَاةِ وَقَدْ جَاءُوْهُ كَالْحُمَمِ", "lt": "Ka'annahal-ḥaudlu tabyadldlul-wujûhu bihî ۞ minal-‘ushâti wa qad jâ'ûhu kal-ḥumami", "id": "Ia (Al-Qur'an) bagaikan telaga (Kautsar) yang memutihkan wajah para pendosa, padahal mereka datang kepadanya hitam bagaikan arang.", "no": 14},
{"ar": "وَكَالصِّرَاطِ وَكَالْمِيْزَانِ مَعْدِلَةً ۞ فَالْقِسْطُ مِنْ غَيْرِهَا فِي النَّاسِ لَمْ يَقُمِ", "lt": "Wa kash-shirâṭi wa kal-mîzâni ma‘dilatan ۞ fal-qisṭu min ghairihâ fin-nâsi lam yaqumi", "id": "Bagaikan shirath dan timbangan dalam keadilannya; maka keadilan tidak akan tegak di tengah manusia tanpa (berpedoman kepada)nya.", "no": 15},
{"ar": "لَا تَعْجَبَنْ لِحَسُوْدٍ رَاحَ يُنْكِرُهَا ۞ تَجَاهُلًا وَهْوَ عَيْنُ الْحَاذِقِ الْفَهِمِ", "lt": "Lâ ta‘jaban liḥasûdin râḥa yunkiruhâ ۞ tajâhulan wahwa ‘ainul-ḥâdziqil-fahimi", "id": "Janganlah engkau heran terhadap orang dengki yang mengingkarinya dengan pura-pura tidak tahu, padahal ia adalah orang yang cerdas dan paham.", "no": 16},
{"ar": "قَدْ تُنْكِرُ الْعَيْنُ ضَوْءَ الشَّمْسِ مِنْ رَمَدٍ ۞ وَيُنْكِرُ الْفَمُ طَعْمَ الْمَاءِ مِنْ سَقَمِ", "lt": "Qad tunkirul-‘ainu dlau'asy-syamsi min ramadin ۞ wa yunkirul-famu ṭa‘mal-mâ'i min saqami", "id": "Terkadang mata mengingkari cahaya matahari karena sakit mata, dan mulut mengingkari rasa air karena sakit.", "no": 17}]},
{judul:"Fasal 7: Isra' Mi'raj",isi:[
{"ar": "يَا خَيْرَ مَنْ يَمَّمَ الْعَافُوْنَ سَاحَتَهُ ۞ سَعْيًا وَفَوْقَ مُتُوْنِ الْأَيْنُقِ الرُّسُمِ", "lt": "Yâ khaira man yammamal-‘âfûna sâḥatahû ۞ sa‘yan wa fauqa mutûnil-ainuqir-rusumi", "id": "Wahai sebaik-baik orang yang halamannya dituju oleh para peminta, dengan berjalan kaki maupun di atas punggung unta-unta yang cepat.", "no": 1},
{"ar": "وَمَنْ هُوَ الْآيَةُ الْكُبْرَى لِمُعْتَبِرٍ ۞ وَمَنْ هُوَ النِّعْمَةُ الْعُظْمَى لِمُغْتَنِمِ", "lt": "Wa man huwal-âyatul-kubrâ limu‘tabirin ۞ wa man huwan-ni‘matul-‘udhmâ limughtanimi", "id": "Wahai yang menjadi tanda kebesaran paling agung bagi orang yang mau mengambil pelajaran, dan nikmat paling besar bagi orang yang mau memanfaatkannya.", "no": 2},
{"ar": "سَرَيْتَ مِنْ حَرَمٍ لَيْلًا إِلَى حَرَمٍ ۞ كَمَا سَرَى الْبَدْرُ فِيْ دَاجٍ مِنَ الظُّلَمِ", "lt": "Sarauta min ḥaramin lailan ilâ ḥaramin ۞ kamâ saral-badru fî dâjin minadh-dhulami", "id": "Engkau berjalan di malam hari dari tanah haram (Makkah) ke tanah haram (Baitul Maqdis), sebagaimana purnama berjalan di tengah gelapnya malam.", "no": 3},
{"ar": "وَبِتَّ تَرْقَى إِلَى أَنْ نِلْتَ مَنْزِلَةً ۞ مِنْ قَابِ قَوْسَيْنِ لَمْ تُدْرَكْ وَلَمْ تُرَمِ", "lt": "Wa bitta tarqâ ilâ an nilta manzilatan ۞ min qâbi qausaini lam tudrak wa lam turami", "id": "Malam itu engkau terus naik hingga mencapai kedudukan sejarak dua busur panah, kedudukan yang tak pernah dicapai dan tak pernah dicita-citakan (oleh siapa pun).", "no": 4},
{"ar": "وَقَدَّمَتْكَ جَمِيْعُ الْأَنْبِيَاءِ بِهَا ۞ وَالرُّسْلِ تَقْدِيْمَ مَخْدُوْمٍ عَلَى خَدَمِ", "lt": "Wa qaddamatka jamî‘ul-anbiyâ'i bihâ ۞ war-rusli taqdîma makhdûmin ‘alâ khadami", "id": "Seluruh nabi dan rasul mendahulukanmu di sana (sebagai imam), sebagaimana tuan didahulukan atas para pelayannya.", "no": 5},
{"ar": "وَأَنْتَ تَخْتَرِقُ السَّبْعَ الطِّبَاقَ بِهِمْ ۞ فِيْ مَوْكِبٍ كُنْتَ فِيْهِ صَاحِبَ الْعَلَمِ", "lt": "Wa anta takhtariqus-sab‘aṭ-ṭibâqa bihim ۞ fî maukibin kunta fîhi shâḥibal-‘alami", "id": "Engkau menembus tujuh lapis langit melewati mereka, dalam iring-iringan yang engkaulah pembawa panjinya.", "no": 6},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 7},
{"ar": "حَتَّى إِذَا لَمْ تَدَعْ شَأْوًا لِمُسْتَبِقٍ ۞ مِنَ الدُّنُوِّ وَلَا مَرْقًى لِمُسْتَنِمِ", "lt": "Ḥattâ idzâ lam tada‘ sya'wan limustabiqin ۞ minad-dunuwwi wa lâ marqan limustanimi", "id": "Hingga engkau tidak menyisakan lagi jarak kedekatan bagi orang yang hendak berlomba, dan tidak pula tempat naik bagi orang yang hendak mendaki.", "no": 8},
{"ar": "خَفَضْتَ كُلَّ مَقَامٍ بِالْإِضَافَةِ إِذْ ۞ نُوْدِيْتَ بِالرَّفْعِ مِثْلَ الْمُفْرَدِ الْعَلَمِ", "lt": "Khafadlta kulla maqâmin bil-idlâfati idz ۞ nûdîta bir-raf‘i mitslal-mufradil-‘alami", "id": "Engkau rendahkan setiap kedudukan dengan perbandingan (kedudukanmu), ketika engkau dipanggil dengan (panggilan) yang tinggi, bagaikan (nama) tunggal yang masyhur.", "no": 9},
{"ar": "كَيْمَا تَفُوْزَ بِوَصْلٍ أَيِّ مُسْتَتِرٍ ۞ عَنِ الْعُيُوْنِ وَسِرٍّ أَيِّ مُكْتَتِمِ", "lt": "Kaimâ tafûza biwashlin ayyi mustatirin ۞ ‘anil-‘uyûni wa sirrin ayyi muktatimi", "id": "Agar engkau beruntung dengan pertemuan yang tersembunyi dari pandangan mata, dan rahasia yang sangat tersimpan.", "no": 10},
{"ar": "فَحُزْتَ كُلَّ فَخَارٍ غَيْرَ مُشْتَرَكٍ ۞ وَجُزْتَ كُلَّ مَقَامٍ غَيْرَ مُزْدَحَمِ", "lt": "Faḥuzta kulla fakhârin ghaira musytarakin ۞ wa juzta kulla maqâmin ghaira muzdaḥami", "id": "Maka engkau meraih segala kebanggaan yang tidak dimiliki selainmu, dan engkau melewati setiap kedudukan tanpa berdesakan.", "no": 11},
{"ar": "وَجَلَّ مِقْدَارُ مَا وُلِّيْتَ مِنْ رُتَبٍ ۞ وَعَزَّ إِدْرَاكُ مَا أُوْلِيْتَ مِنْ نِعَمِ", "lt": "Wa jalla miqdâru mâ wullîta min rutabin ۞ wa ‘azza idrâku mâ ûlîta min ni‘ami", "id": "Agunglah ukuran derajat-derajat yang diberikan kepadamu, dan sulit dijangkau nikmat-nikmat yang dianugerahkan kepadamu.", "no": 12},
{"ar": "بُشْرَى لَنَا مَعْشَرَ الْإِسْلَامِ إِنَّ لَنَا ۞ مِنَ الْعِنَايَةِ رُكْنًا غَيْرَ مُنْهَدِمِ", "lt": "Busyrâ lanâ ma‘syaral-islâmi inna lanâ ۞ minal-‘inâyati ruknan ghaira munhadimi", "id": "Kabar gembira bagi kita, wahai kaum muslimin, sesungguhnya kita memiliki tiang penopang dari pertolongan (Allah) yang tidak akan runtuh.", "no": 13},
{"ar": "لَمَّا دَعَا اللهُ دَاعِيْنَا لِطَاعَتِهِ ۞ بِأَكْرَمِ الرُّسْلِ كُنَّا أَكْرَمَ الْأُمَمِ", "lt": "Lammâ da‘allâhu dâ‘înâ liṭâ‘atihî ۞ bi'akramir-rusli kunnâ akramal-umami", "id": "Ketika Allah menyebut penyeru kita kepada ketaatan-Nya sebagai rasul yang paling mulia, maka kita pun menjadi umat yang paling mulia.", "no": 14}]},
{judul:"Fasal 8: Perjuangan Nabi",isi:[
{"ar": "رَاعَتْ قُلُوْبَ الْعِدَا أَنْبَاءُ بِعْثَتِهِ ۞ كَنَبْأَةٍ أَجْفَلَتْ غُفْلًا مِنَ الْغَنَمِ", "lt": "Râ‘at qulûbal-‘idâ anbâ'u bi‘tsatihî ۞ kanab'atin ajfalat ghuflan minal-ghanami", "id": "Berita kebangkitannya mengejutkan hati para musuh, bagaikan suara (singa) yang mengagetkan kambing-kambing yang sedang lengah.", "no": 1},
{"ar": "مَا زَالَ يَلْقَاهُمُ فِيْ كُلِّ مُعْتَرَكٍ ۞ حَتَّى حَكَوْا بِالْقَنَا لَحْمًا عَلَى وَضَمِ", "lt": "Mâ zâla yalqâhumu fî kulli mu‘tarakin ۞ ḥattâ ḥakau bil-qanâ laḥman ‘alâ wadlami", "id": "Beliau terus menghadapi mereka di setiap medan pertempuran, hingga karena tusukan tombak mereka bagaikan daging di atas talenan.", "no": 2},
{"ar": "وَدُّوا الْفِرَارَ فَكَادُوْا يَغْبِطُوْنَ بِهِ ۞ أَشْلَاءَ شَالَتْ مَعَ الْعِقْبَانِ وَالرَّخَمِ", "lt": "Waddul-firâra fakâdû yaghbiṭûna bihî ۞ asylâ'a syâlat ma‘al-‘iqbâni war-rakhami", "id": "Mereka ingin melarikan diri, hingga hampir-hampir mereka iri kepada potongan-potongan tubuh yang dibawa terbang oleh burung elang dan burung nasar.", "no": 3},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 4},
{"ar": "تَمْضِي اللَّيَالِيْ وَلَا يَدْرُوْنَ عِدَّتَهَا ۞ مَا لَمْ تَكُنْ مِنْ لَيَالِي الْأَشْهُرِ الْحُرُمِ", "lt": "Tamdlil-layâlî wa lâ yadrûna ‘iddatahâ ۞ mâ lam takun min layâlil-asyhuril-ḥurumi", "id": "Malam-malam berlalu tanpa mereka ketahui jumlahnya, kecuali malam-malam bulan haram (saat perang dihentikan).", "no": 5},
{"ar": "كَأَنَّمَا الدِّيْنُ ضَيْفٌ حَلَّ سَاحَتَهُمْ ۞ بِكُلِّ قَرْمٍ إِلَى لَحْمِ الْعِدَا قَرِمِ", "lt": "Ka'annamad-dînu dlaifun ḥalla sâḥatahum ۞ bikulli qarmin ilâ laḥmil-‘idâ qarimi", "id": "Seakan-akan agama ini adalah tamu yang singgah di halaman mereka, bersama setiap pemberani yang haus akan (kekalahan) musuh.", "no": 6},
{"ar": "يَجُرُّ بَحْرَ خَمِيْسٍ فَوْقَ سَابِحَةٍ ۞ يَرْمِيْ بِمَوْجٍ مِنَ الْأَبْطَالِ مُلْتَطِمِ", "lt": "Yajurru baḥra khamîsin fauqa sâbiḥatin ۞ yarmî bimaujin minal-abṭâli multaṭimi", "id": "Beliau memimpin lautan pasukan di atas kuda-kuda yang laju, yang melemparkan gelombang para pahlawan yang saling berbenturan.", "no": 7},
{"ar": "مِنْ كُلِّ مُنْتَدِبٍ لِلّٰهِ مُحْتَسِبٍ ۞ يَسْطُوْ بِمُسْتَأْصِلٍ لِلْكُفْرِ مُصْطَلِمِ", "lt": "Min kulli muntadibin lillâhi muḥtasibin ۞ yasṭû bimusta'shilin lil-kufri mushṭalimi", "id": "Dari setiap orang yang menyambut seruan Allah dan mengharap pahala, yang menyerang dengan (senjata) yang mencabut dan membinasakan kekafiran sampai ke akarnya.", "no": 8},
{"ar": "حَتَّى غَدَتْ مِلَّةُ الْإِسْلَامِ وَهْيَ بِهِمْ ۞ مِنْ بَعْدِ غُرْبَتِهَا مَوْصُوْلَةَ الرَّحِمِ", "lt": "Ḥattâ ghadat millatul-islâmi wahya bihim ۞ min ba‘di ghurbatihâ maushûlatar-raḥimi", "id": "Hingga agama Islam, dengan (perjuangan) mereka, setelah keterasingannya menjadi tersambung tali kekerabatannya.", "no": 9},
{"ar": "مَكْفُوْلَةً أَبَدًا مِنْهُمْ بِخَيْرِ أَبٍ ۞ وَخَيْرِ بَعْلٍ فَلَمْ تَيْتَمْ وَلَمْ تَئِمِ", "lt": "Makfûlatan abadan minhum bikhairi abin ۞ wa khairi ba‘lin falam taitam wa lam ta'imi", "id": "Selamanya terpelihara oleh mereka dengan sebaik-baik ayah dan sebaik-baik suami, sehingga ia tidak menjadi yatim dan tidak menjadi janda.", "no": 10},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 11},
{"ar": "هُمُ الْجِبَالُ فَسَلْ عَنْهُمْ مُصَادِمَهُمْ ۞ مَاذَا رَأَى مِنْهُمُ فِيْ كُلِّ مُصْطَدَمِ", "lt": "Humul-jibâlu fasal ‘anhum mushâdimahum ۞ mâdzâ ra'â minhumu fî kulli mushṭadami", "id": "Mereka bagaikan gunung; tanyakanlah tentang mereka kepada musuh yang berhadapan dengan mereka, apa yang dilihatnya dari mereka di setiap pertempuran.", "no": 12},
{"ar": "وَسَلْ حُنَيْنًا وَسَلْ بَدْرًا وَسَلْ أُحُدًا ۞ فُصُوْلَ حَتْفٍ لَهُمْ أَدْهَى مِنَ الْوَخَمِ", "lt": "Wa sal ḥunainan wa sal badran wa sal uḥudan ۞ fushûla ḥatfin lahum adhâ minal-wakhami", "id": "Tanyakanlah kepada (Perang) Hunain, Badar, dan Uhud; (di sana ada) musim-musim kematian bagi musuh yang lebih dahsyat daripada wabah.", "no": 13},
{"ar": "الْمُصْدِرِي الْبِيْضِ حُمْرًا بَعْدَ مَا وَرَدَتْ ۞ مِنَ الْعِدَا كُلَّ مُسْوَدٍّ مِنَ اللِّمَمِ", "lt": "Al-mushdiril-bîdli ḥumran ba‘da mâ waradat ۞ minal-‘idâ kulla muswaddin minal-limami", "id": "Mereka mengembalikan pedang-pedang yang putih dalam keadaan merah, setelah pedang itu mendatangi setiap kepala musuh yang berambut hitam.", "no": 14},
{"ar": "وَالْكَاتِبِيْنَ بِسُمْرِ الْخَطِّ مَا تَرَكَتْ ۞ أَقْلَامُهُمْ حَرْفَ جِسْمٍ غَيْرَ مُنْعَجِمِ", "lt": "Wal-kâtibîna bisumril-khaṭṭi mâ tarakat ۞ aqlâmuhum ḥarfa jismin ghaira mun‘ajimi", "id": "Mereka \"menulis\" dengan tombak-tombak cokelat dari Khaththi; pena-pena mereka tidak meninggalkan satu \"huruf\" tubuh (musuh) pun tanpa bertitik (luka).", "no": 15},
{"ar": "شَاكِي السِّلَاحِ لَهُمْ سِيْمَى تُمَيِّزُهُمْ ۞ وَالْوَرْدُ يَمْتَازُ بِالسِّيْمَا مِنَ السَّلَمِ", "lt": "Syâkis-silâḥi lahum sîmâ tumayyizuhum ۞ wal-wardu yamtâzu bis-sîmâ minas-salami", "id": "Mereka bersenjata lengkap dan memiliki tanda yang membedakan mereka, sebagaimana bunga mawar berbeda dengan pohon salam karena tandanya.", "no": 16},
{"ar": "تُهْدِيْ إِلَيْكَ رِيَاحُ النَّصْرِ نَشْرَهُمُ ۞ فَتَحْسَبُ الزَّهْرَ فِي الْأَكْمَامِ كُلَّ كَمِيْ", "lt": "Tuhdî ilaika riyâḥun-nashri nasyrahumu ۞ fataḥsabuz-zahra fil-akmâmi kulla kamî", "id": "Angin kemenangan membawa harum mereka kepadamu, sehingga engkau mengira setiap pahlawan berbaju besi adalah bunga di dalam kelopaknya.", "no": 17},
{"ar": "كَأَنَّهُمْ فِيْ ظُهُوْرِ الْخَيْلِ نَبْتُ رُبًا ۞ مِنْ شِدَّةِ الْحَزْمِ لَا مِنْ شِدَّةِ الْحُزُمِ", "lt": "Ka'annahum fî dhuhûril-khaili nabtu rubâ ۞ min syiddatil-ḥazmi lâ min syiddatil-ḥuzumi", "id": "Di atas punggung kuda mereka bagaikan tanaman yang kokoh di atas bukit, karena kuatnya tekad, bukan karena kencangnya tali pelana.", "no": 18},
{"ar": "طَارَتْ قُلُوْبُ الْعِدَا مِنْ بَأْسِهِمْ فَرَقًا ۞ فَمَا تُفَرِّقُ بَيْنَ الْبَهْمِ وَالْبُهَمِ", "lt": "Ṭârat qulûbul-‘idâ min ba'sihim faraqan ۞ famâ tufarriqu bainal-bahmi wal-buhami", "id": "Hati para musuh terbang ketakutan karena keberanian mereka, hingga tak dapat membedakan anak kambing dari para pahlawan.", "no": 19},
{"ar": "وَمَنْ تَكُنْ بِرَسُوْلِ اللهِ نُصْرَتُهُ ۞ إِنْ تَلْقَهُ الْأُسْدُ فِيْ آجَامِهَا تَجِمِ", "lt": "Wa man takun birasûlillâhi nushratuhû ۞ in talqahul-usdu fî âjâmihâ tajimi", "id": "Siapa yang pertolongannya bersama Rasulullah, jika singa-singa menjumpainya di sarang mereka, singa-singa itu pun akan diam ketakutan.", "no": 20},
{"ar": "وَلَنْ تَرَى مِنْ وَلِيٍّ غَيْرِ مُنْتَصِرٍ ۞ بِهِ وَلَا مِنْ عَدُوٍّ غَيْرِ مُنْقَصِمِ", "lt": "Wa lan tarâ min waliyyin ghairi muntashirin ۞ bihî wa lâ min ‘aduwwin ghairi munqashimi", "id": "Engkau tidak akan melihat seorang pengikutnya kecuali mendapat kemenangan karenanya, dan tidak pula seorang musuhnya kecuali hancur.", "no": 21},
{"ar": "أَحَلَّ أُمَّتَهُ فِيْ حِرْزِ مِلَّتِهِ ۞ كَاللَّيْثِ حَلَّ مَعَ الْأَشْبَالِ فِيْ أَجَمِ", "lt": "Aḥalla ummatahû fî ḥirzi millatihî ۞ kal-laitsi ḥalla ma‘al-asybâli fî ajami", "id": "Beliau menempatkan umatnya di dalam benteng agamanya, bagaikan singa yang tinggal bersama anak-anaknya di dalam sarang.", "no": 22},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 23},
{"ar": "كَمْ جَدَّلَتْ كَلِمَاتُ اللهِ مِنْ جَدِلٍ ۞ فِيْهِ وَكَمْ خَصَمَ الْبُرْهَانُ مِنْ خَصِمِ", "lt": "Kam jaddalat kalimâtullâhi min jadilin ۞ fîhi wa kam khashamal-burhânu min khashimi", "id": "Betapa banyak penentang beliau yang dibantah oleh kalam Allah, dan betapa banyak lawan yang dikalahkan oleh bukti-bukti (kebenarannya).", "no": 24},
{"ar": "كَفَاكَ بِالْعِلْمِ فِي الْأُمِّيِّ مُعْجِزَةً ۞ فِي الْجَاهِلِيَّةِ وَالتَّأْدِيْبِ فِي الْيُتُمِ", "lt": "Kafâka bil-‘ilmi fil-ummiyyi mu‘jizatan ۞ fil-jâhiliyyati wat-ta'dîbi fil-yutumi", "id": "Cukuplah sebagai mukjizat bagimu: ilmu pada diri seorang yang ummi di zaman jahiliah, dan adab yang luhur pada diri seorang yatim.", "no": 25}]},
{judul:"Fasal 9: Tawassul kepada Nabi",isi:[
{"ar": "خَدَمْتُهُ بِمَدِيْحٍ أَسْتَقِيْلُ بِهِ ۞ ذُنُوْبَ عُمْرٍ مَضَى فِي الشِّعْرِ وَالْخِدَمِ", "lt": "Khadamtuhû bimadîḥin astaqîlu bihî ۞ dzunûba ‘umrin madlâ fisy-syi‘ri wal-khidami", "id": "Aku mengabdi kepadanya dengan pujian (qasidah ini), yang dengannya aku memohon ampunan atas dosa-dosa umurku yang telah berlalu dalam syair dan pengabdian (kepada penguasa).", "no": 1},
{"ar": "إِذْ قَلَّدَانِيَ مَا تُخْشَى عَوَاقِبُهُ ۞ كَأَنَّنِيْ بِهِمَا هَدْيٌ مِنَ النَّعَمِ", "lt": "Idz qalladâniya mâ tukhsyâ ‘awâqibuhû ۞ ka'annanî bihimâ hadyun minan-na‘ami", "id": "Karena keduanya telah mengalungkan kepadaku sesuatu yang ditakutkan akibatnya, seakan-akan karena keduanya aku bagaikan ternak kurban (yang dikalungi).", "no": 2},
{"ar": "أَطَعْتُ غَيَّ الصِّبَا فِي الْحَالَتَيْنِ وَمَا ۞ حَصَلْتُ إِلَّا عَلَى الْآثَامِ وَالنَّدَمِ", "lt": "Aṭa‘tu ghayyash-shibâ fil-ḥâlataini wa mâ ۞ ḥashaltu illâ ‘alal-âtsâmi wan-nadami", "id": "Aku telah menuruti kesesatan masa muda dalam kedua keadaan itu, dan aku tidak memperoleh apa-apa kecuali dosa dan penyesalan.", "no": 3},
{"ar": "فَيَا خَسَارَةَ نَفْسٍ فِيْ تِجَارَتِهَا ۞ لَمْ تَشْتَرِ الدِّيْنَ بِالدُّنْيَا وَلَمْ تَسُمِ", "lt": "Fayâ khasârata nafsin fî tijâratihâ ۞ lam tasytarid-dîna bid-dunyâ wa lam tasumi", "id": "Alangkah ruginya jiwa dalam perniagaannya, ia tidak membeli agama dengan dunia, bahkan tidak pula menawarnya.", "no": 4},
{"ar": "وَمَنْ يَبِعْ آجِلًا مِنْهُ بِعَاجِلِهِ ۞ يَبِنْ لَهُ الْغَبْنُ فِيْ بَيْعٍ وَفِيْ سَلَمِ", "lt": "Wa man yabi‘ âjilan minhu bi‘âjilihî ۞ yabin lahul-ghabnu fî bai‘in wa fî salami", "id": "Siapa yang menjual (kebahagiaan) akhirat dengan (kesenangan) dunia, akan tampak baginya kerugian dalam jual beli tunai maupun pesanan.", "no": 5},
{"ar": "إِنْ آتِ ذَنْبًا فَمَا عَهْدِيْ بِمُنْتَقِضٍ ۞ مِنَ النَّبِيِّ وَلَا حَبْلِيْ بِمُنْصَرِمِ", "lt": "In âti dzanban famâ ‘ahdî bimuntaqidlin ۞ minan-nabiyyi wa lâ ḥablî bimunsharimi", "id": "Jika aku melakukan dosa, janjiku kepada Nabi tidaklah batal dan taliku (dengan beliau) tidaklah putus.", "no": 6},
{"ar": "فَإِنَّ لِيْ ذِمَّةً مِنْهُ بِتَسْمِيَتِيْ ۞ مُحَمَّدًا وَهْوَ أَوْفَى الْخَلْقِ بِالذِّمَمِ", "lt": "Fa inna lî dzimmatan minhu bitasmiyatî ۞ muḥammadan wahwa aufal-khalqi bidz-dzimami", "id": "Sesungguhnya aku memiliki jaminan dari beliau karena namaku Muhammad, dan beliau adalah makhluk yang paling menepati janji.", "no": 7},
{"ar": "إِنْ لَمْ يَكُنْ فِيْ مَعَادِيْ آخِذًا بِيَدِيْ ۞ فَضْلًا وَإِلَّا فَقُلْ يَا زَلَّةَ الْقَدَمِ", "lt": "In lam yakun fî ma‘âdî âkhidzan biyadî ۞ fadllan wa illâ faqul yâ zallatal-qadami", "id": "Jika di hari kebangkitanku beliau tidak memegang tanganku dengan karunianya, maka katakanlah: Alangkah celakanya kaki yang tergelincir.", "no": 8},
{"ar": "حَاشَاهُ أَنْ يُحْرَمَ الرَّاجِيْ مَكَارِمَهُ ۞ أَوْ يَرْجِعَ الْجَارُ مِنْهُ غَيْرَ مُحْتَرَمِ", "lt": "Ḥâsyâhu an yuḥramar-râjî makârimahû ۞ au yarji‘al-jâru minhu ghaira muḥtarami", "id": "Mustahil beliau membiarkan orang yang berharap terhalang dari kemurahannya, atau membiarkan orang yang meminta perlindungan pulang tanpa dihormati.", "no": 9},
{"ar": "وَمُنْذُ أَلْزَمْتُ أَفْكَارِيْ مَدَائِحَهُ ۞ وَجَدْتُهُ لِخَلَاصِيْ خَيْرَ مُلْتَزِمِ", "lt": "Wa mundzu alzamtu afkârî madâ'iḥahû ۞ wajadtuhû likhalâshî khaira multazimi", "id": "Sejak aku menetapkan pikiranku untuk memujinya, aku dapati beliau sebaik-baik penjamin keselamatanku.", "no": 10},
{"ar": "وَلَنْ يَفُوْتَ الْغِنَى مِنْهُ يَدًا تَرِبَتْ ۞ إِنَّ الْحَيَا يُنْبِتُ الْأَزْهَارَ فِي الْأَكَمِ", "lt": "Wa lan yafûtal-ghinâ minhu yadan taribat ۞ innal-ḥayâ yunbitul-azhâra fil-akami", "id": "Kekayaan darinya tidak akan luput dari tangan yang miskin, sebagaimana hujan menumbuhkan bunga-bunga di atas bukit.", "no": 11},
{"ar": "وَلَمْ أُرِدْ زَهْرَةَ الدُّنْيَا الَّتِي اقْتَطَفَتْ ۞ يَدَا زُهَيْرٍ بِمَا أَثْنَى عَلَى هَرِمِ", "lt": "Wa lam urid zahratad-dunyal-latiq-taṭafat ۞ yadâ zuhairin bimâ atsnâ ‘alâ harimi", "id": "Aku tidak menginginkan perhiasan dunia yang dipetik oleh kedua tangan Zuhair karena pujiannya kepada Harim.", "no": 12},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 13}]},
{judul:"Fasal 10: Munajat dan Doa",isi:[
{"ar": "يَا أَكْرَمَ الْخَلْقِ مَا لِيْ مَنْ أَلُوْذُ بِهِ ۞ سِوَاكَ عِنْدَ حُلُوْلِ الْحَادِثِ الْعَمِمِ", "lt": "Yâ akramal-khalqi mâ lî man alûdzu bihî ۞ siwâka ‘inda ḥulûlil-ḥâditsil-‘amimi", "id": "Wahai makhluk yang paling mulia, tidak ada bagiku tempat berlindung selain engkau ketika datang peristiwa yang dahsyat dan menyeluruh.", "no": 1},
{"ar": "وَلَنْ يَضِيْقَ رَسُوْلَ اللهِ جَاهُكَ بِيْ ۞ إِذَا الْكَرِيْمُ تَجَلَّى بِاسْمِ مُنْتَقِمِ", "lt": "Wa lan yadlîqa rasûlallâhi jâhuka bî ۞ idzal-karîmu tajallâ bismi muntaqimi", "id": "Wahai Rasulullah, kedudukanmu tidak akan sempit untuk menolongku, ketika (Allah) Yang Maha Mulia menampakkan diri dengan nama-Nya Al-Muntaqim (Yang Maha Membalas).", "no": 2},
{"ar": "فَإِنَّ مِنْ جُوْدِكَ الدُّنْيَا وَضَرَّتَهَا ۞ وَمِنْ عُلُوْمِكَ عِلْمَ اللَّوْحِ وَالْقَلَمِ", "lt": "Fa inna min jûdikad-dunyâ wa dlarratahâ ۞ wa min ‘ulûmika ‘ilmal-lauḥi wal-qalami", "id": "Sesungguhnya di antara kemurahanmu adalah dunia dan akhirat, dan di antara ilmumu adalah ilmu Lauh (Mahfuzh) dan Qalam.", "no": 3},
{"ar": "يَا نَفْسُ لَا تَقْنَطِيْ مِنْ زَلَّةٍ عَظُمَتْ ۞ إِنَّ الْكَبَائِرَ فِي الْغُفْرَانِ كَاللَّمَمِ", "lt": "Yâ nafsu lâ taqnaṭî min zallatin ‘adhumat ۞ innal-kabâ'ira fil-ghufrâni kal-lamami", "id": "Wahai jiwa, janganlah berputus asa karena kesalahan yang besar, sesungguhnya dosa-dosa besar dalam ampunan (Allah) bagaikan dosa-dosa kecil.", "no": 4},
{"ar": "لَعَلَّ رَحْمَةَ رَبِّيْ حِيْنَ يَقْسِمُهَا ۞ تَأْتِيْ عَلَى حَسَبِ الْعِصْيَانِ فِي الْقِسَمِ", "lt": "La‘alla raḥmata rabbî ḥîna yaqsimuhâ ۞ ta'tî ‘alâ ḥasabil-‘ishyâni fil-qisami", "id": "Semoga rahmat Tuhanku, ketika Dia membaginya, datang sesuai kadar kedurhakaan dalam pembagiannya.", "no": 5},
{"ar": "يَا رَبِّ وَاجْعَلْ رَجَائِيْ غَيْرَ مُنْعَكِسٍ ۞ لَدَيْكَ وَاجْعَلْ حِسَابِيْ غَيْرَ مُنْخَرِمِ", "lt": "Yâ rabbi waj‘al rajâ'î ghaira mun‘akisin ۞ ladaika waj‘al ḥisâbî ghaira munkharimi", "id": "Wahai Tuhanku, jadikanlah harapanku di sisi-Mu tidak berbalik (sia-sia), dan jadikanlah perhitunganku tidak meleset.", "no": 6},
{"ar": "وَالْطُفْ بِعَبْدِكَ فِي الدَّارَيْنِ إِنَّ لَهُ ۞ صَبْرًا مَتَى تَدْعُهُ الْأَهْوَالُ يَنْهَزِمِ", "lt": "Walṭuf bi‘abdika fid-dâraini inna lahû ۞ shabran matâ tad‘uhul-ahwâlu yanhazimi", "id": "Kasihanilah hamba-Mu di dunia dan akhirat, karena ia memiliki kesabaran yang akan kalah bila dipanggil oleh berbagai kengerian.", "no": 7},
{"ar": "وَائْذَنْ لِسُحْبِ صَلَاةٍ مِنْكَ دَائِمَةٍ ۞ عَلَى النَّبِيِّ بِمُنْهَلٍّ وَمُنْسَجِمِ", "lt": "Wa'dzan lisuḥbi shalâtin minka dâ'imatin ۞ ‘alan-nabiyyi bimunhallin wa munsajimi", "id": "Izinkanlah awan-awan shalawat dari-Mu yang terus-menerus tercurah kepada Nabi dengan deras dan berlimpah.", "no": 8},
{"ar": "وَالْآلِ وَالصَّحْبِ ثُمَّ التَّابِعِيْنَ فَهُمْ ۞ أَهْلُ التُّقَى وَالنَّقَى وَالْحِلْمِ وَالْكَرَمِ", "lt": "Wal-âli wash-shaḥbi tsummat-tâbi‘îna fahum ۞ ahlut-tuqâ wan-naqâ wal-ḥilmi wal-karami", "id": "Juga kepada keluarga, para sahabat, kemudian para tabi‘in, karena mereka adalah orang-orang yang bertakwa, suci, penyabar, dan mulia.", "no": 9},
{"ar": "مَا رَنَّحَتْ عَذَبَاتِ الْبَانِ رِيْحُ صَبًا ۞ وَأَطْرَبَ الْعِيْسَ حَادِي الْعِيْسِ بِالنَّغَمِ", "lt": "Mâ rannaḥat ‘adzabâtil-bâni rîḥu shabâ ۞ wa aṭrabal-‘îsa ḥâdil-‘îsi bin-naghami", "id": "Selama angin timur menggoyang ranting-ranting pohon Ban, dan selama penggiring unta menggembirakan unta-untanya dengan senandung.", "no": 10},
{"ar": "ثُمَّ الرِّضَا عَنْ أَبِيْ بَكْرٍ وَعَنْ عُمَرٍ ۞ وَعَنْ عَلِيٍّ وَعَنْ عُثْمَانَ ذِي الْكَرَمِ", "lt": "Tsummar-ridlâ ‘an abî bakrin wa ‘an ‘umarin ۞ wa ‘an ‘aliyyin wa ‘an ‘utsmâna dzil-karami", "id": "Kemudian (limpahkanlah) keridaan kepada Abu Bakar, Umar, Ali, dan Utsman yang dermawan.", "no": 11},
{"ar": "وَاغْفِرْ إِلٰهِيْ لِكُلِّ الْمُسْلِمِيْنَ بِمَا ۞ يَتْلُوْهُ فِي الْمَسْجِدِ الْأَقْصَى وَفِي الْحَرَمِ", "lt": "Waghfir ilâhî likullil-muslimîna bimâ ۞ yatlûhu fil-masjidil-aqshâ wa fil-ḥarami", "id": "Ampunilah, wahai Tuhanku, seluruh kaum muslimin, berkat apa yang mereka baca di Masjidil Aqsha dan di Masjidil Haram.", "no": 12},
{"ar": "بِجَاهِ مَنْ بَيْتُهُ فِيْ طَيْبَةٍ حَرَمٌ ۞ وَاسْمُهُ قَسَمٌ مِنْ أَعْظَمِ الْقَسَمِ", "lt": "Bijâhi man baituhû fî ṭaibatin ḥaramun ۞ wasmuhû qasamun min a‘dhamil-qasami", "id": "Demi kemuliaan (Nabi) yang rumahnya di Thaibah (Madinah) menjadi tanah haram, dan namanya menjadi sumpah yang paling agung.", "no": 13},
{"ar": "وَهٰذِهِ بُرْدَةُ الْمُخْتَارِ قَدْ خُتِمَتْ ۞ وَالْحَمْدُ لِلّٰهِ فِيْ بَدْءٍ وَفِيْ خَتَمِ", "lt": "Wa hâdzihî burdatul-mukhtâri qad khutimat ۞ wal-ḥamdu lillâhi fî bad'in wa fî khatami", "id": "Inilah Burdah (pujian untuk Nabi) yang terpilih, telah selesai; segala puji bagi Allah di awal dan di akhir.", "no": 14},
{"ar": "أَبْيَاتُهَا قَدْ أَتَتْ سِتِّيْنَ مَعْ مِائَةٍ ۞ فَرِّجْ بِهَا كَرْبَنَا يَا وَاسِعَ الْكَرَمِ", "lt": "Abyâtuhâ qad atat sittîna ma‘ mi'atin ۞ farrij bihâ karbanâ yâ wâsi‘al-karami", "id": "Bait-baitnya berjumlah seratus enam puluh; dengannya lapangkanlah kesusahan kami, wahai Yang Maha Luas kemurahan-Nya.", "no": 15},
{"ar": "آمِيْنَ", "lt": "Âmîn", "id": "Kabulkanlah (ya Allah).", "no": 16}]}]});
